import React, { useState } from "react";
import Quadrant from "./components/Quadrant";
import "./styles/App.css";

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({ 1: "", 2: "", 3: "", 4: "" });

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return;
    const newTask = {
      id: Date.now(),
      text: taskInputs[quadrant],
      quadrant,
      completed: false,
      dueDate: null,
      timer: 0,
      isRunning: false,
    };
    setTasks([...tasks, newTask]);
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter((task) => task.id !== taskId));
  };

  return (
    <div className="container-fluid">
      <h1 className="text-center my-4">Eisenhower Matrix</h1>
      <div className="row">
        {[1, 2, 3, 4].map((quadrant) => (
          <Quadrant
            key={quadrant}
            quadrant={quadrant}
            tasks={tasks}
            addTask={addTask}
            deleteTask={deleteTask}
            taskInputs={taskInputs}
            setTaskInputs={setTaskInputs}
          />
        ))}
      </div>
    </div>
  );
}

export default App;
